std::complex<double> FFPMccTtilde(int j1, int j2, int j3, int j4, int j5, int j6, FArray2D<std::complex<double>>& za, FArray2D<std::complex<double>>& zb) {
  auto zab2 = [&za, &zb](int i1, int i2, int i3, int i4) {
    return za(i1, i2) * zb(i2, i4) + za(i1, i3) * zb(i3, i4);
  };
  auto zab = [&za, &zb](int i1, int i2, int i3) {
    return za(i1, i2) * zb(i2, i3);
  };

  std::complex<double> FFPMccTtilde_result =
      1.0 / (zab2(j1, j2, j3, j4) * zab2(j3, j1, j4, j2))
      * (0.5 * (zab(j4, j1, j3) - zab(j4, j2, j3)) * zab2(j5, j1, j4, j6)
         + zab(j5, j1, j3) * zab(j4, j2, j6)
         + zab2(j4, j1, j2, j3) / zab2(j3, j1, j2, j4)
           * (zab(j5, j2, j4) * zab(j3, j1, j6)
              - zab(j3, j1, j4) * (zab(j5, j2, j6) - zab(j5, j3, j6))))
      - zb(j1, j3) * za(j4, j5) * zab2(j2, j1, j3, j6)
        / (zab2(j3, j1, j2, j4) * t(j1, j2, j3));

  FFPMccTtilde_result = FFPMccTtilde_result;  // @coverage-probe
  return FFPMccTtilde_result;
}

extern "C" {
  std::complex<double> FFPMccTtilde_wrapper(int j1, int j2, int j3, int j4, int j5, int j6, std::complex<double>* za_ptr, std::complex<double>* zb_ptr) {
    FArray2D<std::complex<double>> za(za_ptr, mxpart, mxpart);
    FArray2D<std::complex<double>> zb(zb_ptr, mxpart, mxpart);

    return FFPMccTtilde(j1, j2, j3, j4, j5, j6, za, zb);
  }
}
